  --ds-motion-delay-standard: 0s;
  --ds-motion-delay-slow: 0s;
}

.ds-visually-hidden {
  border: 0;
  clip: rect(0 0 0 0);
  height: 1px;
  margin: -1px;
  overflow: hidden;
  padding: 0;
  position: absolute;
  width: 1px;
  white-space: nowrap;
  outline: 0;
  appearance: none;
  left: 0;
}
[dir=rtl] .ds-visually-hidden {
  left: auto;
  right: 0;
}
